// 1. Inputs base y desanidado tolerante
const input = $input.item.json || {};
const periodo = input.periodo || 'Periodo no especificado';
const chartUrl = input.chart_url || '';
const fechaStr = new Date().toISOString().split('T')[0];

function parseSeguro(valor, fallback) {
  if (!valor || String(valor).trim() === '') return fallback;
  try { return typeof valor === 'string' ? JSON.parse(valor) : valor; } catch (e) { return fallback; }
}

// 2. Extraer hotelConfig desde el input
const hotelConfig = parseSeguro(input.hotelConfig, {});
const hotelNombre = hotelConfig.nombre || 'Hotel Baiona';
const capacidadTotal = Number(hotelConfig.capacidad_total || 75);
const ratingReferencia = Number(hotelConfig.rating_referencia || 4.7);
const ciudadHotel = hotelConfig.ubicacion?.ciudad || 'Baiona';
const reglasPricing = hotelConfig.reglas_pricing || {};
const sueloAjustePct = Math.round((Number(reglasPricing.suelo_ajuste || 0.75) - 1) * 100);
const techoAjustePct = Math.round((Number(reglasPricing.techo_ajuste || 1.35) - 1) * 100);

// 3. Parsear conjuntos de datos
const est = parseSeguro(input.estadisticas, {});
const ctxExt = parseSeguro(input.contexto_externo, {});
const tablaDiaria = parseSeguro(input.tabla_diaria, []);
const tablaHistorico = parseSeguro(input.tabla_historico, []);
const tablaCompetencia = parseSeguro(input.tabla_competencia, []);
const ingresosResumen = parseSeguro(input.ingresos_resumen, {});
const perfilDemanda = parseSeguro(input.tabla_perfil_demanda, {});


let totalPeriodo = {};
try { 
  const mn = parseSeguro(input.metricas_negocio, {});
  totalPeriodo = mn.total || {};
} catch (e) {}

let serieDiariaMetricas = [];
try { 
  const mn = parseSeguro(input.metricas_negocio, {});
  serieDiariaMetricas = mn.diario || [];
} catch (e) {}

function pct(v) { return v !== undefined && v !== null ? (Number(v) * 100).toFixed(1) + '%' : 'N/A'; }
function formatearFechaCorta(iso) {
  if (!iso) return iso;
  const d = new Date(iso + 'T00:00:00');
  return d.toLocaleDateString('es-ES', { day: 'numeric', month: 'short' });
}

function extraerPrecioNumerico(val) {
  if (val === null || val === undefined) return null;
  if (typeof val === 'number') return !isNaN(val) && val > 0 ? val : null;
  if (typeof val === 'object') {
    const p = val.precio ?? val.rate ?? val.valor ?? val.amount ?? null;
    return extraerPrecioNumerico(p);
  }
  const str = String(val).trim();
  const match = str.match(/[\d]+(?:[.,]\d+)?/);
  if (!match) return null;
  const num = parseFloat(match[0].replace(',', '.'));
  return !isNaN(num) && num > 0 ? num : null;
}

// 4. Formateador de Markdown a HTML para Anexo I
function formatearMarkdownAHTML(markdown) {
  if (!markdown) return '';
  let html = String(markdown)
    .replace(/<img[^>]*>/gi, '')
    .replace(/^#\s+(.*)$/gm, '<h3 style="color:#1e3a8a; border-bottom:1px solid #e5e7eb; padding-bottom:4px; margin-top:16px; margin-bottom:8px; font-size:13px; font-weight:bold;">$1</h3>')
    .replace(/^##\s+(.*)$/gm, '<h4 style="color:#1e40af; border-bottom:1px solid #f1f5f9; padding-bottom:3px; margin-top:12px; margin-bottom:6px; font-size:12px; font-weight:bold;">$1</h4>')
    .replace(/^###\s+(.*)$/gm, '<div style="background:#f1f5f9; border-left:3px solid #1e40af; padding:4px 8px; margin-top:8px; margin-bottom:4px; border-radius:0 3px 3px 0;"><h5 style="color:#1e40af; margin:0; font-size:11px; font-weight:bold;">$1</h5></div>')
    .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
    .replace(/^\s*-\s+(.*)$/gm, '<li style="margin-bottom:3px; color:#475569; list-style-type:disc; font-size:11px;">$1</li>');

  html = html.replace(/(<li[\s\S]*?<\/li>)+/g, '<ul style="padding-left:18px; margin:4px 0 8px 0;">$&</ul>');

  return html.split('\n').map(l => {
    const trimmed = l.trim();
    if (!trimmed) return '';
    if (trimmed.startsWith('<h') || trimmed.startsWith('<div') || trimmed.startsWith('<ul') || trimmed.startsWith('<li')) {
      return trimmed;
    }
    return `<p style="margin:2px 0 4px 0; line-height:1.4; font-size:11px; color:#475569;">${trimmed}</p>`;
  }).join('');
}

const narrativaLLMCompleta = formatearMarkdownAHTML(input.narrativa_html);

// 5. PARSER ROBUSTO: Diagnóstico y Órdenes de Carga en Tablas (Soporta "Ventana X:" y "Periodo:")
function parsearEstrategiaATablas(textoOriginal) {
  if (!textoOriginal) return '';
  const texto = String(textoOriginal);

  // A. Diagnóstico Operativo
  const filasDiag = [];
  const lineas = texto.split('\n');

  lineas.forEach(l => {
    const t = l.trim();
    if (/^[-*]?\s*Balance General:/i.test(t)) {
      filasDiag.push(`<tr><td style="padding:6px 10px; border:1px solid #d1d5db; font-weight:bold; width:28%;">Balance General</td><td style="padding:6px 10px; border:1px solid #d1d5db;">${t.replace(/^[-*]?\s*Balance General:\s*/i, '')}</td></tr>`);
    } else if (/^[-*]?\s*Comportamiento del Ritmo/i.test(t)) {
      filasDiag.push(`<tr style="background:#f9fafb;"><td style="padding:6px 10px; border:1px solid #d1d5db; font-weight:bold;">Ritmo (Pickup)</td><td style="padding:6px 10px; border:1px solid #d1d5db;">${t.replace(/^[-*]?\s*Comportamiento del Ritmo(\s*\(Pickup\))?:\s*/i, '')}</td></tr>`);
    } else if (/^[-*]?\s*D[ií]as Cr[ií]ticos/i.test(t)) {
      filasDiag.push(`<tr><td style="padding:6px 10px; border:1px solid #d1d5db; font-weight:bold; color:#dc2626;">Días Críticos / Riesgo</td><td style="padding:6px 10px; border:1px solid #d1d5db; color:#dc2626; font-weight:bold;">${t.replace(/^[-*]?\s*D[ií]as Cr[ií]ticos(\s*\/\s*Riesgo)?:\s*/i, '')}</td></tr>`);
    } else if (/^[-*]?\s*Variables Externas:/i.test(t)) {
      filasDiag.push(`<tr style="background:#f9fafb;"><td style="padding:6px 10px; border:1px solid #d1d5db; font-weight:bold;">Variables Externas</td><td style="padding:6px 10px; border:1px solid #d1d5db;">${t.replace(/^[-*]?\s*Variables Externas:\s*/i, '')}</td></tr>`);
    } else if (/^[-*]?\s*Presi[oó]n (?:Competitiva|de Distribuci[oó]n):/i.test(t)) {
      filasDiag.push(`<tr><td style="padding:6px 10px; border:1px solid #d1d5db; font-weight:bold;">Presión de Distribución</td><td style="padding:6px 10px; border:1px solid #d1d5db;">${t.replace(/^[-*]?\s*Presi[oó]n (?:Competitiva|de Distribuci[oó]n):\s*/i, '')}</td></tr>`);
    }
  });

  const tablaDiagHtml = filasDiag.length > 0 ? `
    <h3 style="color:#1e3a8a; font-size:14px; margin:16px 0 8px 0;">📊 Diagnóstico Operativo y Factores Críticos</h3>
    <table style="width:100%; border-collapse:collapse; font-size:12px; margin-bottom:16px;">
      ${filasDiag.join('')}
    </table>` : '';

  // B. Órdenes de Carga por Canal (Ventanas o Periodos)
  const regexPeriodo = /(?:###\s+)?(?:Periodo|Ventana\s*\d*):\s*([^\n]+)([\s\S]*?)(?=(?:(?:###\s+)?(?:Periodo|Ventana\s*\d*):|$))/gi;
  let match;
  const filasOrdenes = [];
  let contador = 0;

  while ((match = regexPeriodo.exec(texto)) !== null) {
    contador++;
    const periodoNombre = match[1].replace(/\*\*/g, '').trim();
    const contenidoBloque = match[2];

    function extraerCanal(patronCanal) {
      const reg = new RegExp(`[-*]?\\s*${patronCanal}[\\s\\S]*?(?=(?:[-*]\\s*(?:Web|OTAs|Canal Directo|Periodo|Ventana:)|$))`, 'i');
      const m = contenidoBloque.match(reg);
      if (!m) return { tarifa: '-', restriccion: '-', asignacion: '-' };
      const sub = m[0];
      const tMatch = sub.match(/(?:Tarifa a cargar|Tarifa recomendada|Tarifa suelo permitida|Tarifa telef[oó]nica|Tarifa)[^:]*:\s*([^\n]+)/i);
      const rMatch = sub.match(/Restricci[oó]n:\s*([^\n]+)/i);
      const aMatch = sub.match(/(?:Asignaci[oó]n de cupo|Pol[ií]tica de cierre(?: r[aá]pido)?):\s*([^\n]+)/i);

      return {
        tarifa: tMatch ? tMatch[1].trim() : '-',
        restriccion: rMatch ? rMatch[1].trim() : '-',
        asignacion: aMatch ? aMatch[1].trim() : '-'
      };
    }

    const web = extraerCanal('(?:Web Propia|Motor)');
    const otas = extraerCanal('(?:OTAs|Booking)');
    const directo = extraerCanal('(?:Canal Directo|Tel[eé]fono|Mostrador)');

    filasOrdenes.push(`
      <tr style="${contador % 2 === 0 ? 'background:#f9fafb;' : ''}">
        <td style="padding:8px; border:1px solid #d1d5db; font-weight:bold; color:#1e3a8a; white-space:nowrap;">${periodoNombre}</td>
        <td style="padding:8px; border:1px solid #d1d5db;">
          <strong>${web.tarifa}</strong>
          ${web.restriccion !== '-' ? `<br><span style="font-size:11px; color:#4b5563;">${web.restriccion}</span>` : ''}
        </td>
        <td style="padding:8px; border:1px solid #d1d5db;">
          <strong>${otas.tarifa}</strong>
          ${otas.restriccion !== '-' ? `<br><span style="font-size:11px; color:#4b5563;">${otas.restriccion}</span>` : ''}
        </td>
        <td style="padding:8px; border:1px solid #d1d5db;">
          <strong>${directo.tarifa}</strong>
          ${directo.asignacion !== '-' ? `<br><span style="font-size:11px; color:#4b5563;">${directo.asignacion}</span>` : ''}
        </td>
        <td style="padding:8px; border:1px solid #d1d5db; font-size:11px; color:#374151;">
          ${web.asignacion !== '-' ? web.asignacion : 'Cupo Dinámico'}
        </td>
      </tr>
    `);
  }

  const tablaOrdenesHtml = filasOrdenes.length > 0 ? `
    <h3 style="color:#1e3a8a; font-size:14px; margin:20px 0 8px 0;">💰 Órdenes de Carga en Canales (PMS & Channel Manager)</h3>
    <div style="overflow-x:auto;">
      <table style="width:100%; border-collapse:collapse; font-size:12px;">
        <tr style="background:#eff6ff; color:#1e3a8a;">
          <th style="padding:8px; border:1px solid #d1d5db; text-align:left;">Ventana / Periodo</th>
          <th style="padding:8px; border:1px solid #d1d5db; text-align:left;">Web Propia / Motor</th>
          <th style="padding:8px; border:1px solid #d1d5db; text-align:left;">OTAs (Booking / Expedia)</th>
          <th style="padding:8px; border:1px solid #d1d5db; text-align:left;">Canal Directo (Tel./Walk-in)</th>
          <th style="padding:8px; border:1px solid #d1d5db; text-align:left;">Cupo Asignado</th>
        </tr>
        ${filasOrdenes.join('')}
      </table>
    </div>` : '';

  return `${tablaDiagHtml}${tablaOrdenesHtml}`;
}

let narrativaEstructuradaHtml = parsearEstrategiaATablas(input.narrativa_html);

// Fallback por si la narrativa no contiene bloques regex reconocibles
if (!narrativaEstructuradaHtml) {
  narrativaEstructuradaHtml = `
    <div style="background:#f8fafc; border:1px solid #e2e8f0; border-radius:6px; padding:12px; font-size:12px; color:#475569;">
      Las directrices operativas completas, desglosadas por canal y restricciones, se encuentran disponibles en el <strong>Anexo I (Hoja de Ruta y Estrategia Redactada Completa)</strong>.
    </div>
  `;
}

// 6. Pickup y Métricas Base
let pickupCalculado = totalPeriodo.pickup_pace?.pickup_7_medio ?? totalPeriodo.pickup_pace?.pickup_medio_7d ?? null;
if (pickupCalculado === null || isNaN(pickupCalculado)) {
  const pickupsValidos = (Array.isArray(tablaDiaria) ? tablaDiaria : [])
    .map(d => parseFloat(d.pickup_7))
    .filter(v => !isNaN(v) && v !== null);
  if (pickupsValidos.length > 0) {
    pickupCalculado = (pickupsValidos.reduce((a, b) => a + b, 0) / pickupsValidos.length).toFixed(1);
  }
}
const pickupPropio = (pickupCalculado !== null && !isNaN(pickupCalculado)) ? `${Number(pickupCalculado).toFixed(1)} hab` : '0.0 hab';

const adrPropio = Number(
  totalPeriodo.ingresos?.adr_medio ||
  est?.adr_medio ||
  (Array.isArray(tablaDiaria) && tablaDiaria.length > 0 
    ? tablaDiaria.reduce((acc, d) => acc + (Number(d.adr_eur) || 0), 0) / tablaDiaria.length 
    : 0)
);

const revparPropio = Number(
  totalPeriodo.ingresos?.revpar_medio ||
  (Array.isArray(tablaDiaria) && tablaDiaria.length > 0
    ? tablaDiaria.reduce((acc, d) => acc + (Number(d.revpar_eur) || 0), 0) / tablaDiaria.length
    : 0)
);

// Cálculo de RevPAR Neto Estimado (Descontando ~18% de comisión en cuota Booking observada)
const cuotaBooking = perfilDemanda?.canal ? (perfilDemanda.canal.find(c => /booking/i.test(c.valor))?.pct ?? 92.9) : 92.9;
const comisionEfectiva = (cuotaBooking / 100) * 0.18;
const revparNetoEstimado = revparPropio * (1 - comisionEfectiva);
const costeComisionTotal = (Number(ingresosResumen.totales_previstos || 0) * comisionEfectiva);

// 7. Tarjeta Configuración Hotel
const bloqueConfigHotel = `
<div style="background:#f1f5f9; border-left:4px solid #1e3a8a; border-radius:4px; padding:10px 14px; margin-bottom:16px; font-size:12px; color:#334155;">
  <strong>🏨 Establecimiento:</strong> ${hotelNombre} &nbsp;|&nbsp; 
  <strong>Capacidad:</strong> ${capacidadTotal} habs &nbsp;|&nbsp; 
  <strong>Rating Ref.:</strong> ⭐ ${ratingReferencia.toFixed(1)} &nbsp;|&nbsp; 
  <strong>Destino:</strong> ${ciudadHotel} &nbsp;|&nbsp; 
  <strong>Límites Yielding:</strong> [${sueloAjustePct}%, +${techoAjustePct}%]
</div>`;

// 8. Contexto de Mercado (Sin N/A molestos)
const totalDias = Array.isArray(tablaDiaria) ? tablaDiaria.length : 0;
const diasLluvia = Array.isArray(tablaDiaria) ? tablaDiaria.filter(d => d.lluvia === 'Sí' || d.lluvia === 'Si').length : 0;

const precipitaciones = (Array.isArray(tablaDiaria) ? tablaDiaria : [])
  .map(d => parseFloat(d.precipitacion_mm))
  .concat(serieDiariaMetricas.map(d => parseFloat((d.contexto_externo?.clima || d.clima)?.precipitacion)))
  .filter(v => !isNaN(v) && v !== null);
const totalMm = precipitaciones.length ? precipitaciones.reduce((a, b) => a + b, 0).toFixed(1) : '0.0';

const tempsMax = (Array.isArray(tablaDiaria) ? tablaDiaria : [])
  .map(d => parseFloat(d.temp_max))
  .concat(serieDiariaMetricas.map(d => parseFloat((d.contexto_externo?.clima || d.clima)?.temp_max ?? d.temp_max)))
  .filter(v => !isNaN(v) && v !== null);

const tempsMin = (Array.isArray(tablaDiaria) ? tablaDiaria : [])
  .map(d => parseFloat(d.temp_min))
  .concat(serieDiariaMetricas.map(d => parseFloat((d.contexto_externo?.clima || d.clima)?.temp_min ?? d.temp_min)))
  .filter(v => !isNaN(v) && v !== null);

const maxTemp = tempsMax.length ? Math.max(...tempsMax).toFixed(1) + ' °C' : null;
const minTemp = tempsMin.length ? Math.min(...tempsMin).toFixed(1) + ' °C' : null;

const preciosComp = Array.isArray(tablaCompetencia)
  ? tablaCompetencia.map(h => extraerPrecioNumerico(h.precio ?? h.tarifa ?? h.rate)).filter(p => p !== null)
  : [];
const maxPrecioComp = preciosComp.length ? Math.max(...preciosComp).toFixed(0) + ' €' : null;
const minPrecioComp = preciosComp.length ? Math.min(...preciosComp).toFixed(0) + ' €' : null;

const ratingsComp = Array.isArray(tablaCompetencia)
  ? tablaCompetencia.map(h => parseFloat(h.rating)).filter(r => !isNaN(r) && r > 0)
  : [];
const ratingMedioComp = ratingsComp.length ? (ratingsComp.reduce((a, b) => a + b, 0) / ratingsComp.length).toFixed(1) : null;

const elementosContexto = [
  `🗓️ <strong>Festivos:</strong> ${ctxExt.dias_festivos ?? 0}d`,
  `🎒 <strong>Vacaciones escolares:</strong> ${ctxExt.dias_vacaciones_escolares ?? 0}d`,
  maxTemp && minTemp ? `🌡️ <strong>Temp. máx/mín:</strong> ${maxTemp} / ${minTemp}` : null,
  `🌧️ <strong>Lluvia:</strong> ${diasLluvia}/${totalDias}d (${totalMm} mm)`,
  minPrecioComp && maxPrecioComp ? `🏨 <strong>Precios comp.:</strong> ${minPrecioComp} - ${maxPrecioComp} ${ratingMedioComp ? `(⭐ ${ratingMedioComp})` : ''}` : null
].filter(Boolean);

const bloqueContexto = `
<div style="background:#f8fafc; border:1px solid #e2e8f0; border-radius:8px; padding:12px 16px; margin: 16px 0;">
  <h3 style="margin: 0 0 8px 0; color:#1e3a8a; font-size:14px;">Contexto del Mercado y Entorno</h3>
  <p style="margin:0; font-size:13px; color:#475569; line-height:1.6;">
    ${elementosContexto.join(' &nbsp;|&nbsp; ')}
  </p>
</div>`;

// 9. Bloque de Ingresos y Rentabilidad Neta
let bloqueIngresos = '';
if (ingresosResumen && ingresosResumen.totales_previstos !== undefined && ingresosResumen.totales_previstos !== null) {
  const yoyTexto = ingresosResumen.yoy_pct !== null && ingresosResumen.yoy_pct !== undefined
    ? `${ingresosResumen.yoy_pct >= 0 ? '+' : ''}${ingresosResumen.yoy_pct}% vs año anterior`
    : 'Sin comparativa YoY disponible';
  bloqueIngresos = `
  <div style="display:flex; gap:12px; flex-wrap:wrap; margin: 14px 0 16px 0;">
    <div style="background:#eff6ff; border-radius:8px; padding:12px 16px; flex:1; min-width:140px; border:1px solid #dbeafe;">
      <div style="font-size:12px; color:#4b5563; font-weight:600;">Ingresos Previstos</div>
      <div style="font-size:20px; font-weight:bold; color:#1e3a8a; margin-top:2px;">${Number(ingresosResumen.totales_previstos).toLocaleString('es-ES', {minimumFractionDigits: 2, maximumFractionDigits: 2})} €</div>
    </div>
    <div style="background:#f0fdf4; border-radius:8px; padding:12px 16px; flex:1; min-width:140px; border:1px solid #dcfce7;">
      <div style="font-size:12px; color:#4b5563; font-weight:600;">Actuales (Confirmados)</div>
      <div style="font-size:20px; font-weight:bold; color:#166534; margin-top:2px;">${Number(ingresosResumen.totales_actuales ?? 0).toLocaleString('es-ES', {minimumFractionDigits: 2, maximumFractionDigits: 2})} €</div>
    </div>
    <div style="background:#fefce8; border-radius:8px; padding:12px 16px; flex:1; min-width:140px; border:1px solid #fef9c3;">
      <div style="font-size:12px; color:#4b5563; font-weight:600;">Año Anterior</div>
      <div style="font-size:20px; font-weight:bold; color:#854d0e; margin-top:2px;">${ingresosResumen.totales_anio_anterior !== null && ingresosResumen.totales_anio_anterior !== undefined ? Number(ingresosResumen.totales_anio_anterior).toLocaleString('es-ES', {minimumFractionDigits: 2, maximumFractionDigits: 2}) + ' €' : 'N/A'}</div>
    </div>
    <div style="background:#faf5ff; border-radius:8px; padding:12px 16px; flex:1; min-width:140px; border:1px solid #f3e8ff;">
      <div style="font-size:12px; color:#6b21a8; font-weight:600;">RevPAR Neto Est.</div>
      <div style="font-size:20px; font-weight:bold; color:#6b21a8; margin-top:2px;">${revparNetoEstimado.toFixed(2)} €</div>
      <div style="font-size:10px; color:#9333ea; margin-top:2px;">Coste comisiones: ~${Math.round(costeComisionTotal).toLocaleString('es-ES')} €</div>
    </div>
  </div>
  <p style="font-size:12px; color:#6b7280; margin:-8px 0 16px 2px;">
    <strong>Variación Ingresos:</strong> ${yoyTexto}${ingresosResumen.dias_sin_dato_yoy ? ` · ${ingresosResumen.dias_sin_dato_yoy} de${ingresosResumen.dias_totales} días sin dato histórico comparable` : ''}
  </p>`;
}

// 10. Resumen Ejecutivo de Pricing por Canal
const tablaResumenPricingCanal = `
<h3 style="color:#1e3a8a; font-size:14px; margin:16px 0 8px 0;">🌐 Resumen de Pricing y Condiciones por Canal</h3>
<table style="width:100%; border-collapse:collapse; font-size:12px; margin-bottom:16px;">
  <tr style="background:#eff6ff; color:#1e3a8a;">
    <th style="padding:7px 10px; border:1px solid #d1d5db; text-align:left;">Canal</th>
    <th style="padding:7px 10px; border:1px solid #d1d5db; text-align:left;">Rango Tarifario</th>
    <th style="padding:7px 10px; border:1px solid #d1d5db; text-align:left;">Restricción Habitual</th>
    <th style="padding:7px 10px; border:1px solid #d1d5db; text-align:left;">Política / Asignación</th>
  </tr>
  <tr>
    <td style="padding:7px 10px; border:1px solid #d1d5db; font-weight:bold;">Web Propia / Motor</td>
    <td style="padding:7px 10px; border:1px solid #d1d5db;">100.18 € &ndash; 139.98 €</td>
    <td style="padding:7px 10px; border:1px solid #d1d5db;">MinLOS 1&ndash;2 noches</td>
    <td style="padding:7px 10px; border:1px solid #d1d5db;">Canal pivote tractor / Proteger cupo en alta</td>
  </tr>
  <tr style="background:#f9fafb;">
    <td style="padding:7px 10px; border:1px solid #d1d5db; font-weight:bold;">OTAs (Booking / Expedia)</td>
    <td style="padding:7px 10px; border:1px solid #d1d5db;">114.87 € &ndash; 163.65 €</td>
    <td style="padding:7px 10px; border:1px solid #d1d5db;">MinLOS 1&ndash;2 noches</td>
    <td style="padding:7px 10px; border:1px solid #d1d5db;">Recargo del +10% al +18% para absorción de comisiones</td>
  </tr>
  <tr>
    <td style="padding:7px 10px; border:1px solid #d1d5db; font-weight:bold;">Canal Directo (Tel./Mostrador)</td>
